  IEnumerator Setup(StormboundRun r,Action<SessionSave> edit=null){yield return r.Open();var s=r.Paused();Rest(s);edit?.Invoke(s);yield return r.Prepare(s);yield return r.Begin();}
  void Verdict(StormboundRun r,string id,bool pass,string expected){r.Observe(id);r.Check(id,pass,expected,JsonUtility.ToJson(r.Read()));}
  static double Stock(SessionSave s,string port,string kind)=>V(A(s,"island-"+port),kind);
  static void Job(SessionSave s,int id,int job)=>N(A(s,"resident-"+id),"job",job);
  static void Supplies(SessionSave s,int amount=200){foreach(var port in new[]{"a","b"})foreach(var item in new[]{"food","timber","ore"})N(A(s,"island-"+port),item,amount);}
  static void Kill(SessionSave s,int id){var a=A(s,"resident-"+id);a.state="dead";N(a,"health",0);N(a,"job",0);N(a,"morale",0);}
  static void Esc(SessionSave s,int stage,int work,bool paid=true,bool active=true){N(s,"escape_stage",stage);N(s,"escape_work",work);N(s,"escape_paid",paid?1:0);N(s,"escape_active",active?1:0);A(s,"escape-project").state=new[]{"hull","rigging","departure","complete"}[stage];}
  [UnityTest] public IEnumerator T01A_PublicEntry(){var r=new StormboundRun("dynamic");return r.Execute(new[]{"D1_SESSION_ENTRY"},Entry(r));}
