  IEnumerator State(StormboundRun r){yield return r.Open();var detached=Call("capture",()=>r.Game.Capture());N(detached,"pressure",99);bool deep=V(r.Read(),"pressure")!=99;var legal=r.Paused();N(A(legal,"island-b"),"food",73);yield return r.Prepare(legal);var copy=r.Read();var bad=SessionFormat.Clone(copy);bad.actors[1].id=bad.actors[0].id;var op=Call("state_restore",()=>r.Game.Restore(bad));yield return null;Verdict(r,"D1_SESSION_STATE",deep&&op!=null&&op.state==OperationState.Rejected&&Same(copy,r.Read())&&Stock(copy,"b","food")==73,"deep capture, complete legal edited restore, atomic duplicate-identity rejection independent of scene object queries");}
