  IEnumerator Fatigue(StormboundRun r){yield return Setup(r,s=>{Job(s,1,1);N(A(s,"resident-1"),"fatigue",80);});var b=r.Read();yield return r.Step();var blocked=r.Read();for(int i=0;i<5;i++)yield return r.Tap(Key.J);yield return r.Step();var rested=r.Read();yield return r.Tap(Key.J);yield return r.Step();var worked=r.Read();Verdict(r,"D2_FATIGUE",Stock(blocked,"a","food")==Stock(b,"a","food")&&V(A(blocked,"resident-1"),"fatigue")==90&&V(A(rested,"resident-1"),"fatigue")==70&&V(A(worked,"resident-1"),"fatigue")==80&&Stock(worked,"a","food")==Stock(rested,"a","food")+3-6,"fatigue blocks, explicit job/rest recovers, later night work occurs once before consumption");}
