  [UnityTest] public IEnumerator T08_BuildAndGuards(){var r=new StormboundRun("dynamic");return r.Execute(new[]{"D2_BUILD","D3_BUILD_GUARDS"},Build(r));}
  IEnumerator Build(StormboundRun r){bool guards=true;yield return Setup(r,s=>{N(s,"selected_building",2);Job(s,1,4);Job(s,2,4);});var initial=r.Read();yield return r.Tap(Key.C);guards&=Same(initial,r.Read(),false);yield return r.Tap(Key.B);yield return r.Tap(Key.C);var paid=r.Read();yield return r.Tap(Key.C);guards&=Same(paid,r.Read(),false);yield return r.Step(2);var complete=r.Read();bool built=A(complete,"a-workshop").state=="built"&&Stock(paid,"a","timber")==Stock(initial,"a","timber")-8&&Stock(paid,"a","ore")==Stock(initial,"a","ore")-2;yield return r.Tap(Key.C);guards&=Same(complete,r.Read(),false);Verdict(r,"D2_BUILD",built,"normal order pays once, two builders finish workshop in two periods");yield return Setup(r,s=>{N(A(s,"island-a"),"timber",0);});initial=r.Read();yield return r.Tap(Key.C);guards&=Same(initial,r.Read(),false);Verdict(r,"D3_BUILD_GUARDS",guards,"missing prerequisite, duplicate, built and unaffordable order are atomic");}
