  [UnityTest] public IEnumerator T10_TransportAtomic(){var r=new StormboundRun("dynamic");return r.Execute(new[]{"D2_FERRY","D3_TRANSPORT_ATOMIC","D3_UNIQUENESS"},Ferry(r));}
  IEnumerator Ferry(StormboundRun r){yield return Setup(r,s=>{N(A(s,"island-a"),"food",1);});yield return r.Tap(Key.Equals);yield return r.Tap(Key.M);var draft=r.Read();yield return r.Tap(Key.T);bool atomic=Same(draft,r.Read(),false);Verdict(r,"D3_TRANSPORT_ATOMIC",atomic,"departure needs cargo plus separate food cost; failure preserves draft and stock");yield return Setup(r);var b=r.Read();yield return r.Tap(Key.Equals);yield return r.Tap(Key.Equals);yield return r.Tap(Key.M);yield return r.Tap(Key.T);var a=r.Read();bool sent=A(a,"ferry").state=="to_b"&&V(A(a,"ferry"),"food")==2&&V(A(a,"ferry"),"remaining")==2&&Stock(a,"a","food")==Stock(b,"a","food")-4;Verdict(r,"D2_FERRY",sent,"normal draft and dispatch atomically pay cargo plus departure cost");var f=r.Observe("aboard-real-identity");Verdict(r,"D3_UNIQUENESS",V(A(a,"ferry"),"passengers")==1&&A(a,"resident-1").state=="aboard"&&V(A(a,"resident-1"),"island")==0&&V(a,"manifest_passengers")==0&&V(a,"manifest_food")==0&&f.actors.Count==3&&f.actors.Select(x=>x.instance_id).Distinct().Count()==f.actors.Count,"passenger identity has one actual object and exclusive boat ownership");}
