  [UnityTest] public IEnumerator T12_Event(){var r=new StormboundRun("dynamic");return r.Execute(new[]{"D2_EVENT","D3_EVENT_ONCE"},Event(r));}
  IEnumerator Event(StormboundRun r){yield return Setup(r,s=>{Date(s,2,0);N(s,"events_resolved",0);N(A(s,"island-a"),"timber",0);});yield return r.Step();var pending=r.Read();yield return r.Wait(.35f);yield return r.Tap(Key.Digit3);yield return r.Tap(Key.N);yield return r.Tap(Key.Digit1);var unchanged=r.Read();bool blocked=pending.phase=="event"&&V(pending,"event_pending")==1&&Same(pending,unchanged,false);var pressure=V(pending,"pressure");yield return r.Tap(Key.Digit2);var resolved=r.Read();yield return r.Tap(Key.Digit2);var again=r.Read();Verdict(r,"D2_EVENT",blocked&&resolved.phase=="playing"&&V(resolved,"pressure")==pressure+5,"scheduled decision halts time and legal refusal applies its consequence");Verdict(r,"D3_EVENT_ONCE",blocked&&V(resolved,"events_resolved")==1&&V(again,"pressure")==V(resolved,"pressure")&&Ticks(again)==Ticks(pending),"unaffordable choice and invalid keys do nothing; later key changes speed but not decision consequence");}
  [UnityTest] public IEnumerator T13_EscapePayment(){var r=new StormboundRun("dynamic");return r.Execute(new[]{"D2_ESCAPE","D3_STAGE_PAYMENT","D3_NO_DOUBLE_WORK"},Escape(r));}
  IEnumerator Escape(StormboundRun r){yield return Setup(r,s=>{Beacons(s);Supplies(s);Job(s,1,4);Job(s,2,4);Building(s,"a-clinic","building",1);});var b=r.Read();yield return r.Tap(Key.E);var paid=r.Read();yield return r.Tap(Key.E);yield return r.Tap(Key.E);var resumed=r.Read();bool charge=Stock(paid,"a","timber")==Stock(b,"a","timber")-12&&Stock(paid,"a","ore")==Stock(b,"a","ore")-4&&Stock(resumed,"a","timber")==Stock(paid,"a","timber");yield return r.Step();var first=r.Read();bool separate=A(first,"a-clinic").state=="built"&&V(first,"escape_work")==0;yield return r.Step();yield return r.Step();var hull=r.Read();Verdict(r,"D3_STAGE_PAYMENT",charge,"begin charges once, suspension and resumption do not repay");Verdict(r,"D3_NO_DOUBLE_WORK",separate,"construction owns builder work for the entire tick including its completion");bool stages=V(hull,"escape_stage")==1&&V(hull,"escape_paid")==0&&V(hull,"escape_work")==0;yield return r.Tap(Key.E);yield return r.Step(2);var rig=r.Read();stages&=V(rig,"escape_stage")==2&&V(rig,"escape_paid")==0;yield return r.Tap(Key.E);var denied=r.Read();stages&=V(denied,"escape_paid")==0;Verdict(r,"D2_ESCAPE",stages,"hull and rigging complete sequentially; final stage cannot start with survivors away");}
