  [UnityTest] public IEnumerator T15_PauseSpeed(){var r=new StormboundRun("dynamic");return r.Execute(new[]{"D2_PAUSE","D2_SPEED"},PauseSpeed(r));}
  IEnumerator PauseSpeed(StormboundRun r){yield return Setup(r,s=>N(s,"tick_remainder",1.25));var b=r.Read();yield return r.Wait(.4f);bool freeze=Same(b,r.Read());yield return r.Step();var a=r.Read();bool one=Ticks(a)==Ticks(b)+1&&V(a,"paused")==1&&V(a,"tick_remainder")==0;Verdict(r,"D2_PAUSE",freeze&&one,"pause preserves fractional state; explicit Step advances one period then remains paused");SessionSave reference=null;bool coherent=true;var elapsed=new List<float>();foreach(var key in new[]{Key.Digit1,Key.Digit2,Key.Digit3}){yield return Setup(r,s=>{Date(s,2,0);N(s,"events_resolved",0);Job(s,1,1);Job(s,2,4);Building(s,"a-workshop","building",1);});yield return r.Tap(key);var speed=V(r.Read(),"speed");yield return r.Tap(Key.Escape);var start=Time.realtimeSinceStartup;var deadline=start+4/(float)speed+2;while(r.Read().phase!="event"&&Time.realtimeSinceStartup<deadline)yield return null;elapsed.Add(Time.realtimeSinceStartup-start);var current=r.Read();coherent&=current.phase=="event"&&Ticks(current)==4&&Stock(current,"a","food")==33&&V(A(current,"a-workshop"),"work")==2&&V(A(current,"resident-1"),"fatigue")==10;N(current,"speed",1);N(current,"tick_remainder",0);if(reference==null)reference=current;else coherent&=Same(reference,current);var stopped=r.Read();yield return r.Wait(.25f);coherent&=Same(stopped,r.Read());r.Observe("automatic-speed-"+speed+"-modal-boundary");}coherent&=elapsed[0]>elapsed[1]*2&&elapsed[1]>elapsed[2]*2;Verdict(r,"D2_SPEED",coherent,"1x/4x/16x normal speed controls execute identical automatic work/resources/history and stop at the same decision");}
  [UnityTest] public IEnumerator T16_SaveRestore(){var r=new StormboundRun("dynamic");return r.Execute(new[]{"D2_SAVE_LOAD","D3_DETERMINISM"},SaveRestore(r));}
  IEnumerator SaveRestore(StormboundRun r){yield return Setup(r,s=>{N(s,"tick_remainder",1.375);Building(s,"a-workshop","building",1);Job(s,1,4);});yield return r.Tap(Key.F5);var saved=r.Read();yield return r.Step();yield return r.Tap(Key.Tab);yield return r.Tap(Key.F9);var loaded=r.Read();bool restores=Same(saved,loaded);Verdict(r,"D2_SAVE_LOAD",restores,"disk Load restores fractional time, selections, project and complete history");yield return r.Step();var first=r.Read();yield return r.Tap(Key.F9);yield return r.Step();var second=r.Read();Verdict(r,"D3_DETERMINISM",Same(first,second),"same saved state plus same normal Step repeats state and chronicle without duplicate listeners");}
  [UnityTest] public IEnumerator T17_Endings(){var r=new StormboundRun("dynamic");return r.Execute(new[]{"D2_ENDINGS","D4_TERMINAL_LIFECYCLE"},Endings(r));}
  IEnumerator Endings(StormboundRun r){yield return Setup(r,s=>{Beacons(s);Supplies(s);for(int i=1;i<=6;i++)r.MoveResident(s,i,1);Job(s,1,4);Esc(s,2,2);});yield return r.Step();var won=r.Read();bool success=won.phase=="escaped"&&V(won,"escape_stage")==3;foreach(var key in new[]{Key.N,Key.C,Key.T,Key.J,Key.E,Key.V})yield return r.Tap(key);yield return r.Wait(.3f);bool frozen=Same(won,r.Read(),false);yield return r.Tap(Key.R);bool restart1=r.Read().phase=="playing"&&V(r.Read(),"escape_stage")==0;yield return Setup(r,s=>{Date(s,1,2);for(int i=2;i<=6;i++)Kill(s,i);N(A(s,"resident-1"),"health",10);N(A(s,"island-a"),"food",0);});yield return r.Step();var dead=r.Read();bool failure=dead.phase=="extinct"&&dead.actors.Where(x=>x.kind=="resident").All(x=>x.state=="dead");foreach(var key in new[]{Key.N,Key.C,Key.T,Key.J,Key.E})yield return r.Tap(key);frozen&=Same(dead,r.Read(),false);yield return r.Tap(Key.R);bool restart2=r.Read().phase=="playing"&&r.Read().actors.Count(x=>x.kind=="resident"&&x.state=="alive")==6;Verdict(r,"D2_ENDINGS",success&&failure,"normal final work escapes; normal final night death creates extinction");Verdict(r,"D4_TERMINAL_LIFECYCLE",frozen&&restart1&&restart2,"both results freeze mutable gameplay and retain reusable Restart");}
  [UnityTest] public IEnumerator T18_Adjacent(){var r=new StormboundRun("dynamic");return r.Execute(new[]{"D4_ADJACENT"},Adjacent(r));}
  IEnumerator Adjacent(StormboundRun r){yield return Setup(r,s=>{Supplies(s);Job(s,2,4);Job(s,3,4);});yield return r.Tap(Key.C);yield return r.Step(2);bool built=A(r.Read(),"a-workshop").state=="built";yield return r.Tap(Key.J); // resident1 rest -> forage
  yield return r.Tap(Key.Equals);yield return r.Tap(Key.M);yield return r.Tap(Key.T);yield return r.Step(2);var arrived=r.Read();var before=Stock(arrived,"b","food");yield return r.Step();var worked=r.Read();Verdict(r,"D4_ADJACENT",built&&A(arrived,"ferry").state=="idle_b"&&V(A(arrived,"resident-1"),"island")==2&&Stock(worked,"b","food")==before+3,"normal construction, job assignment, dispatch, arrival and next-tick local work are connected without setup writes");}
  [UnityTest] public IEnumerator T19_ModalContinuity(){var r=new StormboundRun("dynamic");return r.Execute(new[]{"D4_MODAL_CONTINUITY"},ModalContinuity(r));}
  IEnumerator ModalContinuity(StormboundRun r){yield return Setup(r,s=>{Date(s,2,0);N(s,"events_resolved",0);Beacons(s);Esc(s,0,1);var boat=A(s,"ferry");boat.state="to_b";N(boat,"remaining",2);N(boat,"timber",3);N(boat,"passengers",1);r.MoveResident(s,1,0);});yield return r.Step();var pending=r.Read();yield return r.Tap(Key.F5);var saved=r.Read();yield return r.Tap(Key.Digit2);yield return r.Tap(Key.F9);var loaded=r.Read();bool restored=Same(saved,loaded)&&loaded.phase=="event";var pressure=V(loaded,"pressure");yield return r.Tap(Key.Digit2);yield return r.Step();var after=r.Read();Verdict(r,"D4_MODAL_CONTINUITY",pending.phase=="event"&&restored&&V(after,"pressure")==pressure+5&&A(after,"ferry").state=="idle_b"&&V(after,"escape_work")==1,"pending event restores transit and paid stage; one consequence then exactly one arrival");}
  [UnityTest] public IEnumerator T20_Restart(){var r=new StormboundRun("dynamic");return r.Execute(new[]{"D4_RESTART"},Restart(r));}
  IEnumerator Restart(StormboundRun r){bool good=true;foreach(var mode in new[]{0,1,2}){yield return Setup(r,s=>{Date(s,2,0);N(s,"pressure",77);Supplies(s,81);N(s,"speed",16);if(mode==1){s.phase="event";N(s,"event_pending",1);N(s,"events_resolved",0);}if(mode==2){Beacons(s);Esc(s,1,2,true,false);}});yield return r.Tap(Key.R);var fresh=r.Read();good&=fresh.phase=="playing"&&V(fresh,"day")==1&&V(fresh,"period")==0&&V(fresh,"paused")==0&&V(fresh,"speed")==1&&V(fresh,"pressure")==0&&V(fresh,"events_resolved")==0&&V(fresh,"escape_stage")==0&&V(fresh,"chronicle_count")==1&&Stock(fresh,"a","food")==30&&A(fresh,"ferry").state=="idle_a";yield return r.Tap(Key.R);good&=V(r.Read(),"chronicle_count")==1&&r.Read().actors.Count==16;}Verdict(r,"D4_RESTART",good,"dirty pause, event and suspended paid stage reset all initial state repeatedly");}
