  IEnumerator Dirty(StormboundRun r){yield return Setup(r,s=>{Date(s,2,0);N(s,"pressure",37);Building(s,"a-workshop","building",1);var boat=A(s,"ferry");boat.state="to_b";N(boat,"remaining",2);N(boat,"food",3);N(boat,"passengers",1);r.MoveResident(s,1,0);N(s,"tick_remainder",1.25);});yield return r.Tap(Key.F5);r.Observe("dirty-normal-save-before-process-close");var save=r.Read();var path=Path.Combine(Path.GetDirectoryName(Environment.GetEnvironmentVariable("STORMBOUND_EVIDENCE_FILE")),"dirty-close.json");File.WriteAllText(path,JsonUtility.ToJson(new DirtyReceipt{process_id=System.Diagnostics.Process.GetCurrentProcess().Id,save_json=JsonUtility.ToJson(save)},true));}
